[
    {
        "title": "观察条件",
        "description": "题里说这个三角形是等腰三角形，所以两个底角相等；又知道顶角是底角的 $4$ 倍。",
        "bubbleText": "先抓住最关键的两个条件：等腰说明两个底角一样大，顶角还比底角大很多，是它的 $4$ 倍。",
        "bubblePos": {
            "x": 405,
            "y": 92
        }
    },
    {
        "title": "设未知数",
        "description": "设每个底角为 $x^\\circ$。因为两个底角相等，这样设最方便。",
        "bubbleText": "两个底角本来就一样，直接都叫 $x^\\circ$，后面列式会很整齐。",
        "bubblePos": {
            "x": 160,
            "y": 120
        }
    },
    {
        "title": "标出底角",
        "description": "于是这个三角形的两个底角分别都是 $x^\\circ$。",
        "bubbleText": "现在左右两个底角都确定成 $x^\\circ$ 了，未知数已经统一。",
        "bubblePos": {
            "x": 220,
            "y": 448
        }
    },
    {
        "title": "表示顶角",
        "description": "因为顶角是底角的 $4$ 倍，所以顶角是 $4x^\\circ$。",
        "bubbleText": "顶角不用另设新字母，直接写成 $4x^\\circ$，这样三个角就都能用 $x$ 表示。",
        "bubblePos": {
            "x": 602,
            "y": 122
        }
    },
    {
        "title": "利用内角和",
        "description": "三角形内角和是 $180^\\circ$，所以有 $x+x+4x=180$。",
        "bubbleText": "三个角加起来一定是 $180^\\circ$，把刚才表示出的三个角一起加上就行。",
        "bubblePos": {
            "x": 398,
            "y": 522
        }
    },
    {
        "title": "合并同类项",
        "description": "将等式左边合并，得到 $6x=180$。",
        "bubbleText": "左边一共有 $1$ 个 $x$、$1$ 个 $x$ 和 $4$ 个 $x$，合起来就是 $6x$。",
        "bubblePos": {
            "x": 404,
            "y": 286
        }
    },
    {
        "title": "求出底角",
        "description": "解方程得 $x=30$，所以每个底角都是 $30^\\circ$。",
        "bubbleText": "把 $180$ 平均分成 $6$ 份，每份就是 $30$，所以 $x=30$。",
        "bubblePos": {
            "x": 404,
            "y": 372
        }
    },
    {
        "title": "求出顶角",
        "description": "顶角 $=4x=4\\times30=120^\\circ$。",
        "bubbleText": "底角知道后，顶角就是它的 $4$ 倍，所以是 $120^\\circ$。",
        "bubblePos": {
            "x": 610,
            "y": 246
        }
    },
    {
        "title": "检验答案",
        "description": "验算：$30+30+120=180$，满足三角形内角和；并且 $120=4\\times30$，也满足题意。",
        "bubbleText": "再检查两件事：一是三个角和是不是 $180^\\circ$，二是顶角是不是底角的 $4$ 倍，都对。",
        "bubblePos": {
            "x": 404,
            "y": 60
        }
    },
    {
        "title": "得出结论",
        "description": "这个等腰三角形的三个内角分别是 $30^\\circ$、$30^\\circ$、$120^\\circ$。",
        "bubbleText": "最后把答案完整说出来：两个底角都是 $30^\\circ$，顶角是 $120^\\circ$。",
        "bubblePos": {
            "x": 408,
            "y": 566
        }
    }
]
